<?php
declare(strict_types=1);
require_once __DIR__.'/_helper.php';
$extraId=(int)($_GET['extra_id']??0); ekstra_require($extraId);$extra=ekstra_detail($pdo,$extraId);if(!$extra)deny_access();$tp=active_tapel_id($pdo);if(!$tp)exit('Tahun Pelajaran aktif belum tersedia.');
$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$from=$month.'-01';$to=date('Y-m-t',strtotime($from));
$st=$pdo->prepare("SELECT es.id,es.tanggal,es.jam_mulai,es.jam_selesai,es.status FROM ekstra_sesi es WHERE es.ekstrakurikuler_id=? AND es.tahun_pelajaran_id=? AND es.tanggal BETWEEN ? AND ? AND es.status<>'dibatalkan' ORDER BY es.tanggal ASC,es.id ASC");$st->execute([$extraId,$tp,$from,$to]);$sessions=$st->fetchAll();
$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,mk.nama kelas_nama FROM ekstra_anggota eg JOIN siswa s ON s.id=eg.siswa_id LEFT JOIN siswa_kelas sk ON sk.siswa_id=s.id AND sk.tahun_pelajaran_id=eg.tahun_pelajaran_id AND sk.status='aktif' LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE eg.ekstrakurikuler_id=? AND eg.tahun_pelajaran_id=? AND eg.status='aktif' GROUP BY s.id,s.nis,s.nisn,s.nama,mk.nama ORDER BY s.nama");$st->execute([$extraId,$tp]);$students=$st->fetchAll();
$logs=[];if($sessions){$ids=array_map(fn($r)=>(int)$r['id'],$sessions);$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT ea.siswa_id,ea.sesi_id,ea.status FROM ekstra_absensi ea WHERE ea.sesi_id IN ($in)");$st->execute($ids);foreach($st->fetchAll() as $x)$logs[$x['siswa_id'].'|'.$x['sesi_id']]=$x['status'];}
$q=$pdo->prepare('SELECT nama FROM tahun_pelajaran WHERE id=?');$q->execute([$tp]);$tpName=(string)($q->fetchColumn()?:'');
$page_title='Rekap Absensi Peserta';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
<main class="main extra-page"><header class="topbar"><div class="topbar-title">Rekap Absensi Peserta</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content">
<div class="page-header"><div><h1><?=e($extra['nama'])?> · Rekap Absensi Peserta</h1><p>Bulan <?=e(date('F Y',strtotime($from)))?> · Tapel <?=e($tpName)?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>ekstrakurikuler/saya.php">← Kembali</a></div>
<div class="form-card no-print"><form method="get" class="form-actions"><input type="hidden" name="extra_id" value="<?=$extraId?>"><label>Bulan<input type="month" class="form-control" name="month" value="<?=e($month)?>"></label><button class="btn btn-primary">Tampilkan</button></form></div>
<div class="dashboard-table-card"><div class="section-title no-print"><div><h2>Rekap Pertemuan</h2><p>Hanya menampilkan tanggal kegiatan yang benar-benar tercatat. Dokumen bertanda tangan dibuat <strong>per pertemuan</strong>, bukan satu tanda tangan untuk satu bulan.</p></div><button class="btn btn-secondary" onclick="window.print()">🖨 Cetak Ringkasan</button></div>
<div class="table-responsive"><table class="data-table print-table"><thead><tr><th>No</th><th>Tanggal</th><th>Jam</th><th>Status Kegiatan</th><th>Peserta Tercatat</th><th class="no-print">Dokumen</th></tr></thead><tbody><?php if(!$sessions):?><tr><td colspan="6" class="empty-state">Belum ada pertemuan yang tercatat pada bulan ini.</td></tr><?php else:foreach($sessions as $i=>$ss):$cnt=0;foreach($students as $stx){if(isset($logs[$stx['id'].'|'.$ss['id']]))$cnt++;}?><tr><td><?=$i+1?></td><td><?=e(date('d-m-Y',strtotime($ss['tanggal'])))?></td><td><?=e(substr((string)$ss['jam_mulai'],0,5))?><?=!empty($ss['jam_selesai'])?' - '.e(substr((string)$ss['jam_selesai'],0,5)):''?></td><td><?=e(ucfirst((string)$ss['status']))?></td><td><?=$cnt?> / <?=count($students)?></td><td class="no-print"><a class="btn btn-sm btn-primary" href="<?=BASE_URL?>ekstrakurikuler/absensi.php?extra_id=<?=$extraId?>&sesi_id=<?=$ss['id']?>&menu=ekstra_absensi">Lihat / Cetak</a></td></tr><?php endforeach;endif;?></tbody></table></div>
<div class="print-only summary-sign"><div>Mengetahui,<br>Kepala Sekolah<br><br><br>________________________<br>NIP. ____________________</div><div>Pembina/Pelatih<br><br><br><br>________________________<br>NIP. ____________________</div></div>
